SELECT CONCAT(Parentesco, ': ', CASE Escolaridad WHEN 'No Formal Education' THEN 'Sin estudios' WHEN 'Primary' THEN 'Primaria' WHEN 'Secondary' THEN 'Secundaria' WHEN 'Higher Secondary' THEN 'Bachillerato' WHEN 'Bachelor''s Degree' THEN 'Licenciatura' WHEN 'Master''s Degree' THEN 'Maestría' WHEN 'Doctorate' THEN 'Doctorado' ELSE Escolaridad END) AS Educacion_parental, Genero, ROUND(AVG(Nota),2) AS Promedio FROM (SELECT 'Padre' AS Parentesco, father_education_level AS Escolaridad, gender AS Genero, final_grade_pct AS Nota FROM `bi_student_grade_ses_dataset_20261026223437` UNION ALL SELECT 'Madre', mother_education_level, gender, final_grade_pct FROM `bi_student_grade_ses_dataset_20261026223437`) p WHERE Escolaridad IS NOT NULL AND Escolaridad <> '' AND Nota IS NOT NULL GROUP BY Parentesco, Escolaridad, Genero ORDER BY Parentesco, FIELD(Escolaridad,'No Formal Education','Primary','Secondary','Higher Secondary','Bachelor''s Degree','Master''s Degree','Doctorate'), Escolaridad, Genero;
